        el('span', { class: 'kicker', text: 'FITTED PEER MODEL (' + m.train_count + ' TRAIN / ' + m.test_count + ' HELD OUT)' }),
        el('code', { class: 'formula', text: m.formula_line }),
        el('p', { class: 'sub', text: m.split_reason })
